begin;
do $$ declare uid uuid;eng uuid;buyer uuid;req uuid;client uuid;cid uuid;pid uuid;front uuid;center uuid;bid uuid;plan uuid;otherplan uuid;rid uuid;cat public.input_catalog;payload jsonb;u public.profiles;stamp timestamptz;result jsonb;begin
 select id,company_id into uid,cid from public.profiles where role='MASTER' and active limit 1;
 select id into eng from public.profiles where company_id=cid and role='ENGINEERING' and active limit 1;
 select id into buyer from public.profiles where company_id=cid and role='PURCHASING' and active limit 1;
 select id into req from public.profiles where company_id=cid and role='REQUESTER' and active limit 1;
 select id into client from public.profiles where company_id=cid and role='CLIENT' and active limit 1;
 if eng is null or buyer is null or req is null or client is null then raise exception 'Role fixtures required';end if;
 perform set_config('request.jwt.claim.sub',uid::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated')::text,true);
 insert into public.projects(company_id,name,code,created_by) values(cid,'PLANNING ROLLBACK','PLAN-'||left(gen_random_uuid()::text,8),uid) returning id into pid;
 perform public.save_project_access(pid,eng,true,null);perform public.save_project_access(pid,buyer,true,null);perform public.save_project_access(pid,req,true,null);
 select * into cat from public.input_catalog where input_type='MATERIAL' and catalog_active limit 1;
 execute 'set local role authenticated';
 front:=public.save_project_dimension(pid,'{"kind":"FRONT","code":"F1","name":"Fundação"}');
 if public.save_project_dimension(pid,'{"kind":"FRONT","code":"F1","name":"Fundação"}')<>front then raise exception 'Dimension retry duplicated';end if;
 center:=public.save_project_dimension(pid,'{"kind":"COST_CENTER","code":"C1","name":"Materiais"}');
 select updated_at into stamp from public.project_dimensions where id=front;
 perform public.save_project_dimension(pid,jsonb_build_object('id',front,'kind','FRONT','code','F1','name','Fundação','active',false,'updatedAt',stamp));
 if exists(select 1 from public.project_dimensions where id=front and active) then raise exception 'Dimension deactivation failed';end if;
 select updated_at into stamp from public.project_dimensions where id=front;
 perform public.save_project_dimension(pid,jsonb_build_object('id',front,'kind','FRONT','code','F1','name','Fundação','active',true,'updatedAt',stamp));
 bid:=public.save_budget_version(pid,jsonb_build_object('title','Planejamento teste','baseDate','2026-11-07','bdiConfig','{"ac":5.29,"sg":0.25,"r":1,"df":1.01,"l":8,"cp":3.65,"issBase":60,"issRate":5}'::jsonb,'items',jsonb_build_array(jsonb_build_object('inputId',cat.id,'code',cat.catalog_code,'unit',cat.unit,'source','shared','quantity',100,'unitPrice',10))));
 perform public.set_budget_baseline(pid,bid);
 execute 'reset role';
 payload:=jsonb_build_object('clientRequestId','plan-test-'||gen_random_uuid(),'inputId',cat.id,'source','shared','description','tampered','frontId',front,'costCenterId',center,'responsibleId',req,'quantity',5,'priority','URGENT','neededBy',(current_date+14)::text,'leadDays',7,'expectedBudgetId',bid,'notes','Aquisição para concretagem');
 perform set_config('request.jwt.claim.sub',eng::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',eng,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 plan:=public.save_purchase_plan(pid,payload);
 if public.save_purchase_plan(pid,payload)<>plan then raise exception 'Plan retry duplicated';end if;
 if not exists(select 1 from public.purchase_plans where id=plan and description=cat.description and acquisition_deadline=current_date+7 and estimated_unit_price=10) then raise exception 'Plan normalization/deadline/reference failed';end if;
 begin perform public.save_purchase_plan(pid,payload||jsonb_build_object('clientRequestId',gen_random_uuid(),'responsibleId',client));raise exception 'ASSERT Client responsible';exception when others then if sqlerrm='ASSERT Client responsible' then raise;end if;end;
 begin perform public.save_purchase_plan(pid,payload||jsonb_build_object('clientRequestId',gen_random_uuid(),'expectedBudgetId',gen_random_uuid()));raise exception 'ASSERT stale baseline';exception when others then if sqlerrm='ASSERT stale baseline' then raise;end if;end;
 begin perform public.save_purchase_plan(pid,payload||jsonb_build_object('clientRequestId',gen_random_uuid(),'frontId',center));raise exception 'ASSERT invalid dimension';exception when others then if sqlerrm='ASSERT invalid dimension' then raise;end if;end;
 select updated_at into stamp from public.purchase_plans where id=plan;
 begin perform public.purchase_plan_action(plan,'REQUEST',stamp);raise exception 'ASSERT Engineering request';exception when others then if sqlerrm='ASSERT Engineering request' then raise;end if;end;
 begin perform public.list_company_users(pid);raise exception 'ASSERT users exposed to Engineering';exception when others then if sqlerrm='ASSERT users exposed to Engineering' then raise;end if;end;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',uid::text,true);
 select * into u from public.profiles where id=req;
 begin perform public.save_company_user(req,u.name,u.role,false,u.updated_at);raise exception 'ASSERT planned owner disabled';exception when others then if sqlerrm='ASSERT planned owner disabled' or position('Reatribua' in sqlerrm)=0 then raise;end if;end;
 otherplan:=public.save_purchase_plan(pid,payload||jsonb_build_object('clientRequestId',gen_random_uuid(),'responsibleId',uid));
 select updated_at into stamp from public.purchase_plans where id=plan;
 perform set_config('request.jwt.claim.sub',req::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',req,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 if (select count(*) from public.purchase_plans where project_id=pid)<>1 then raise exception 'Requester sees other plans';end if;
 result:=public.purchase_planning_snapshot(pid);
 if jsonb_array_length(result->'plans')<>1 then raise exception 'Snapshot requester scope broken';end if;
 rid:=public.purchase_plan_action(plan,'REQUEST',stamp);
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',buyer::text,true);
 if public.purchase_plan_action(plan,'REQUEST',stamp)<>rid then raise exception 'Second actor duplicated request';end if;
 if not exists(select 1 from public.material_requests where id=rid and purchase_plan_id=plan and front_id=front and cost_center_id=center and responsible_id=req and priority='URGENT' and acquisition_deadline=current_date+7) then raise exception 'Structured request linkage missing';end if;
 if (select count(*) from public.material_requests where purchase_plan_id=plan)<>1 then raise exception 'Duplicate request';end if;
 perform set_config('request.jwt.claim.sub',uid::text,true);
 select updated_at into stamp from public.purchase_plans where id=otherplan;perform public.purchase_plan_action(otherplan,'CANCEL',stamp);
 select * into u from public.profiles where id=req;
 execute 'set local role authenticated';
 begin update public.profiles set role='MASTER' where id=req;raise exception 'ASSERT direct role mutation';exception when others then if sqlerrm='ASSERT direct role mutation' then raise;end if;end;
 perform public.save_company_user(req,'Solicitante editado',u.role,true,u.updated_at);
 execute 'reset role';
 select * into u from public.profiles where id=req;
 begin perform public.save_company_user(req,u.name,u.role,true,'2000-01-01'::timestamptz);raise exception 'ASSERT stale user write';exception when others then if sqlerrm='ASSERT stale user write' then raise;end if;end;
 perform public.save_company_user(req,u.name,u.role,false,u.updated_at);
 if public.member_has_project_access(pid,req) then raise exception 'Disabled account keeps access';end if;
 if not exists(select 1 from public.operation_audit where entity_id=req and action='MANAGE_USER') then raise exception 'User edit not audited';end if;
 perform set_config('request.jwt.claim.sub',req::text,true);
 execute 'set local role authenticated';
 if exists(select 1 from public.projects where id=pid) then raise exception 'Inactive project access leak';end if;
 begin perform public.purchase_planning_snapshot(pid);raise exception 'ASSERT inactive snapshot';exception when others then if sqlerrm='ASSERT inactive snapshot' then raise;end if;end;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',uid::text,true);
 select * into u from public.profiles where id=req;perform public.save_company_user(req,u.name,u.role,true,u.updated_at);
 if public.member_has_project_access(pid,req) then raise exception 'Reactivation restored revoked grants';end if;
 select * into u from public.profiles where id=uid;
 begin perform public.save_company_user(uid,u.name,u.role,false,u.updated_at);raise exception 'ASSERT self disabled';exception when others then if sqlerrm='ASSERT self disabled' then raise;end if;end;
 begin perform public.save_company_user(req,'Test','MASTER',true,now());raise exception 'ASSERT master promotion';exception when others then if sqlerrm='ASSERT master promotion' then raise;end if;end;
 if exists(select 1 from jsonb_array_elements(public.list_company_users(pid)) m where m->>'id'=req::text) then raise exception 'Revoked member still listed as project team';end if;
 if not exists(select 1 from jsonb_array_elements(public.list_company_users(null)) m where m->>'id'=req::text) then raise exception 'Company team misses member';end if;
 update public.projects set client_user_id=client where id=pid;
 select * into u from public.profiles where id=client;
 perform public.save_company_user(client,u.name,'REQUESTER',true,u.updated_at);
 if exists(select 1 from public.projects where id=pid and client_user_id=client) or public.member_has_project_access(pid,client) then raise exception 'Role change kept old client linkage';end if;
end $$;
rollback;
